import { serve } from 'https://deno.land/std@0.208.0/http/server.ts';
import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

// ---- _shared/supabase.ts ---------------------------------------------------------------------
function getServiceClient(): SupabaseClient {
  return createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
  );
}

/**
 * Connection string for functions that talk raw Postgres (deno-postgres / pg).
 * At 1000+ tenants you MUST go through Supavisor in TRANSACTION mode (port 6543)
 * so a burst of concurrent functions doesn't exhaust backend connections.
 * Set SUPABASE_DB_POOL_URL to the "Transaction pooler" URI from
 * Dashboard -> Project Settings -> Database. Falls back to the direct URL.
 * RLS in v2 reads the JWT (no session GUCs) so transaction pooling is safe.
 */
function getPooledConnectionString(): string {
  return (
    Deno.env.get('SUPABASE_DB_POOL_URL') ??
    Deno.env.get('SUPABASE_DB_URL') ??
    ''
  );
}

function corsHeaders(origin = '*') {
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-tenant-id, x-environment',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  };
}

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders(), 'Content-Type': 'application/json' },
  });
}

function errorResponse(message: string, status = 400) {
  return jsonResponse({ error: message }, status);
}

// resolveTenantContext (trusted X-Tenant-Id) and validateApiKey (prefix-only check) were
// removed in Phase 0 (SEC-02 / SEC-04). Use _shared/auth.ts for signed-in users, or
// _shared/ingest-auth.ts (API keys via verify_api_key, site keys via resolve_ingest_site).

// ---- _shared/auth.ts ---------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/secret-box.ts -------------------------------------------------------------------
// Server-side secret sealing (Phase 0 · SEC-05/SEC-07).
//
// Seals tenant secrets (AI provider keys, global-variable secrets) with AES-256-GCM
// using ONE server-only master key: the edge-function secret MARBEE_SECRETS_KEY
// (32 random bytes, base64). The database only ever stores the sealed envelope:
//
//     mbs1.<base64 12-byte IV>.<base64 ciphertext+tag>
//
// The browser never sees the master key or the plaintext. Values written before this
// existed are plaintext ("legacy"); openSecret() still returns them so nothing breaks,
// and callers re-seal them on next use.
//
// Generate a key:  node -e "console.log(require('crypto').randomBytes(32).toString('base64'))"
// Set it:          Supabase Dashboard → Edge Functions → Secrets → MARBEE_SECRETS_KEY

const PREFIX = 'mbs1';
const enc = new TextEncoder();
const dec = new TextDecoder();

let cachedKey: CryptoKey | null = null;
let cachedFrom: string | null = null;

function b64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i += 1) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function unb64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function readMasterKey(): string {
  // deno-lint-ignore no-explicit-any
  const env = (globalThis as any).Deno?.env;
  const v = env?.get('MARBEE_SECRETS_KEY')?.trim();
  if (!v) throw new Error('Server misconfigured: MARBEE_SECRETS_KEY is not set');
  return v;
}

async function masterKey(): Promise<CryptoKey> {
  const material = readMasterKey();
  if (cachedKey && cachedFrom === material) return cachedKey;
  const raw = unb64(material);
  if (raw.length !== 32) throw new Error('MARBEE_SECRETS_KEY must be 32 bytes (base64)');
  cachedKey = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  cachedFrom = material;
  return cachedKey;
}

function isSealed(value: string | null | undefined): boolean {
  return typeof value === 'string' && value.startsWith(`${PREFIX}.`);
}

/** Encrypt a secret for storage. */
async function sealSecret(plaintext: string): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await masterKey(), enc.encode(plaintext)));
  return `${PREFIX}.${b64(iv)}.${b64(ct)}`;
}

/** Decrypt a stored secret. Legacy plaintext is returned as-is; empty → null. Tampered → throws. */
async function openSecret(stored: string | null | undefined): Promise<string | null> {
  if (stored === null || stored === undefined) return null;
  const v = stored.trim();
  if (!v) return null;
  if (!isSealed(v)) return v; // legacy plaintext — caller should re-seal
  const [, ivB64, ctB64] = v.split('.');
  if (!ivB64 || !ctB64) throw new Error('Malformed sealed secret');
  const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, await masterKey(), unb64(ctB64));
  return dec.decode(pt);
}

/** "…abcd" for display. Never reveals more than the last 4 characters. */
function last4(plaintext: string): string {
  const t = plaintext.trim();
  return t.length <= 4 ? '' : t.slice(-4);
}

// ---- _shared/field-crypto.ts -----------------------------------------------------------------
// Field-level encryption with a tenant data key (Phase 0 · SEC-05).
//
// Same format the browser used (apps/web/src/lib/crypto-vault.ts), so existing data
// and logic stay compatible:
//   data key  = 32 random bytes, base64 (stored as an `encryption_key` global variable,
//               itself sealed with MARBEE_SECRETS_KEY — see secret-box.ts)
//   field     = "mbe1.<base64 iv>.<base64 ciphertext+tag>" of JSON.stringify(value)
//
// Data keys now exist only on the server: generated here, sealed at rest, used here.


const FIELD_PREFIX = 'mbe1';
const fieldEnc = new TextEncoder();
const fieldDec = new TextDecoder();

async function importKey(keyB64: string): Promise<CryptoKey> {
  const raw = unb64(keyB64);
  if (raw.length !== 32) throw new Error('Data key must be 32 bytes');
  return crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
}

function generateDataKey(): string {
  return b64(crypto.getRandomValues(new Uint8Array(32)));
}

/** "a1b2 c3d4 e5f6 0718" — first 8 bytes of SHA-256, same as the browser's keyFingerprint. */
async function dataKeyFingerprint(keyB64: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', unb64(keyB64))).slice(0, 8);
  return Array.from(digest).map((b) => b.toString(16).padStart(2, '0')).join('').replace(/(.{4})/g, '$1 ').trim();
}

function isFieldEnvelope(v: unknown): v is string {
  return typeof v === 'string' && v.startsWith(`${FIELD_PREFIX}.`) && v.split('.').length === 3;
}

async function encryptFieldsWithKey(
  data: Record<string, unknown>,
  fieldNames: string[],
  keyB64: string,
): Promise<Record<string, unknown>> {
  const out: Record<string, unknown> = { ...data };
  if (fieldNames.length === 0) return out;
  const key = await importKey(keyB64);
  for (const name of fieldNames) {
    const value = out[name];
    if (value === undefined || value === null || value === '' || isFieldEnvelope(value)) continue;
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, fieldEnc.encode(JSON.stringify(value))));
    out[name] = `${FIELD_PREFIX}.${b64(iv)}.${b64(ct)}`;
  }
  return out;
}

async function decryptFieldsWithKey(
  data: Record<string, unknown>,
  fieldNames: string[],
  keyB64: string,
): Promise<Record<string, unknown>> {
  const out: Record<string, unknown> = { ...data };
  const key = await importKey(keyB64);
  for (const name of fieldNames) {
    const value = out[name];
    if (!isFieldEnvelope(value)) continue;
    try {
      const [, ivB64, ctB64] = value.split('.');
      const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, key, unb64(ctB64));
      out[name] = JSON.parse(fieldDec.decode(pt));
    } catch {
      out[name] = '[decryption failed]';
    }
  }
  return out;
}

// ---- _shared/global-vars.ts ------------------------------------------------------------------
// Server-side access to tenant global variables (Phase 0 · SEC-05).
// Values of kind `secret` / `encryption_key` are sealed with MARBEE_SECRETS_KEY
// (secret-box.ts). Only edge functions (service role) can read the value column (sql/90).


type VariableScope = 'forms' | 'workflows' | 'landing_pages' | 'imports' | 'exports' | 'connectors' | 'all';

/** Plaintext of a tenant variable allowed in `scope`, or null if absent / not allowed. */
async function loadVariablePlaintext(
  svc: SupabaseClient,
  tenantId: string,
  environment: string,
  name: string,
  scope: VariableScope,
): Promise<{ kind: string; plaintext: string } | null> {
  const { data, error } = await svc.from('global_variables')
    .select('id, kind, value, scopes')
    .eq('tenant_id', tenantId).eq('environment', environment).eq('name', name)
    .maybeSingle();
  if (error || !data) return null;
  const scopes = (data.scopes as string[] | null) ?? ['all'];
  if (scope !== 'all' && !scopes.includes('all') && !scopes.includes(scope)) return null;
  // Secrets and keys saved before SEC-05 are in the old browser-encrypted format (mbe1),
  // sealed with a master key the server never had. They can't be opened here — refuse them
  // (never hand out the envelope as if it were the value). The admin must re-enter / rotate.
  if (data.kind !== 'plain' && !isSealed(String(data.value ?? ''))) {
    console.warn('global variable needs re-entry (pre-SEC-05 format)', { tenantId, environment, name });
    return null;
  }
  const plaintext = data.kind === 'plain' ? String(data.value ?? '') : await openSecret(String(data.value ?? ''));
  if (!plaintext) return null;
  await svc.from('global_variables').update({ last_used_at: new Date().toISOString() }).eq('id', data.id);
  return { kind: String(data.kind), plaintext };
}

// ---- global-variables/index.ts ---------------------------------------------------------------
// global-variables — the ONLY way the app manages tenant variables (D-019, Phase 0 · SEC-05).
//
// Before: secret values and encryption keys were sealed in the browser with a "master key"
// kept in ONE admin's localStorage — lost if that storage was cleared, unreadable by the
// server (so hosted CAPTCHA secrets and published-form encryption never worked).
// Now: values are sealed on the server with MARBEE_SECRETS_KEY; encryption keys are
// generated here and never leave the server; app users can't read or write the value
// column directly (sql/90).
//
// Ops (POST JSON, signed-in user JWT; deploy with JWT verification ON):
//   list           { tenant_id?, environment }                       member — secret values never returned
//   create         { tenant_id?, environment, name, kind, value?, description?, scopes? }   api_keys.manage
//   update         { id, value?, description?, scopes? }              api_keys.manage
//   rotate         { id }                                             api_keys.manage (encryption_key)
//   reveal         { id }                                             api_keys.manage, audited (never encryption keys)
//   delete         { id }                                             api_keys.manage
//   encrypt_fields { tenant_id?, environment, key_variable, fields[], data }          member (form previews)
//   decrypt_fields { tenant_id?, environment, key_variable, fields[], records[] }     customers.read


type Json = Record<string, unknown>;
const KINDS = ['plain', 'secret', 'encryption_key'] as const;
const SCOPES = ['forms', 'workflows', 'landing_pages', 'imports', 'exports', 'connectors', 'all'];
const ENVIRONMENTS = ['production', 'staging', 'development'];
const NAME_RE = /^[A-Z0-9_]{1,64}$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PUBLIC_COLUMNS = 'id, tenant_id, environment, name, description, kind, scopes, fingerprint, rotated_at, last_used_at, created_at, updated_at';
const MANAGE = 'api_keys.manage';

function envOf(p: Json): string {
  const e = typeof p.environment === 'string' ? p.environment : 'production';
  if (!ENVIRONMENTS.includes(e)) throw new AuthError(400, 'Invalid environment');
  return e;
}
function scopesOf(v: unknown): string[] {
  if (v === undefined) return ['all'];
  if (!Array.isArray(v) || v.some((s) => typeof s !== 'string' || !SCOPES.includes(s))) throw new AuthError(400, 'Invalid scopes');
  return v.length ? (v as string[]) : ['all'];
}
function textOf(v: unknown, max: number, label: string): string {
  if (typeof v !== 'string') throw new AuthError(400, `${label} must be text`);
  if (v.length > max) throw new AuthError(400, `${label} is too long`);
  return v;
}

async function audit(tenantId: string, environment: string, userId: string, action: string, variableId: string | null, metadata: Json) {
  const { error } = await getServiceClient().from('audit_logs').insert({
    tenant_id: tenantId, environment, user_id: userId, action, resource_type: 'global_variable', resource_id: variableId, metadata,
  });
  if (error) console.error('global-variables: audit insert failed', error.message);
}

/** Load a row by id and check the caller manages its tenant. */
async function loadOwned(user: AuthedUser, id: unknown) {
  if (typeof id !== 'string' || !UUID_RE.test(id)) throw new AuthError(400, 'id must be a UUID');
  const { data, error } = await getServiceClient().from('global_variables').select('*').eq('id', id).maybeSingle();
  if (error) throw new AuthError(500, 'Could not load the variable');
  if (!data) throw new AuthError(404, 'Variable not found');
  await resolveTenant(user, data.tenant_id); // membership
  await requirePermission(user, data.tenant_id as string, MANAGE, 'Manage API keys & variables');
  return data as Json & { id: string; tenant_id: string; environment: string; kind: string; name: string };
}

const ops: Record<string, (u: AuthedUser, p: Json) => Promise<unknown>> = {
  async list(user, p) {
    const tenantId = await resolveTenant(user, p.tenant_id);
    const environment = envOf(p);
    const svc = getServiceClient();
    const { data, error } = await svc.from('global_variables').select(`${PUBLIC_COLUMNS}, value`)
      .eq('tenant_id', tenantId).eq('environment', environment).order('name');
    if (error) throw new AuthError(500, 'Could not list variables');
    // Plain values are config and are returned; secret values and keys never are.
    return {
      variables: (data ?? []).map((r) => ({
        ...r,
        value: r.kind === 'plain' ? r.value : '',
        has_value: Boolean(r.value),
        // Saved before SEC-05 (old browser-encrypted format): unusable until re-entered / rotated.
        needs_reentry: r.kind !== 'plain' && Boolean(r.value) && !isSealed(String(r.value)),
      })),
    };
  },

  async create(user, p) {
    const tenantId = await resolveTenant(user, p.tenant_id);
    await requirePermission(user, tenantId, MANAGE, 'Manage API keys & variables');
    const environment = envOf(p);
    const name = textOf(p.name, 64, 'name');
    if (!NAME_RE.test(name)) throw new AuthError(400, 'Name must be UPPER_SNAKE_CASE (A–Z, 0–9, _)');
    const kind = String(p.kind) as (typeof KINDS)[number];
    if (!KINDS.includes(kind)) throw new AuthError(400, 'Invalid kind');
    let stored: string;
    let fingerprint: string | null = null;
    if (kind === 'encryption_key') {
      // Keys are generated here and never accepted from (or sent to) the browser.
      const key = generateDataKey();
      stored = await sealSecret(key);
      fingerprint = await dataKeyFingerprint(key);
    } else {
      const value = textOf(p.value ?? '', 4000, 'value');
      if (!value) throw new AuthError(400, 'A value is required');
      stored = kind === 'secret' ? await sealSecret(value) : value;
    }
    const now = new Date().toISOString();
    const { data, error } = await getServiceClient().from('global_variables').insert({
      tenant_id: tenantId, environment, name, kind, value: stored, fingerprint,
      description: typeof p.description === 'string' && p.description.trim() ? p.description.trim().slice(0, 500) : null,
      scopes: scopesOf(p.scopes), rotated_at: kind === 'encryption_key' ? now : null,
    }).select(PUBLIC_COLUMNS).single();
    if (error) {
      if (/duplicate|unique/i.test(error.message)) throw new AuthError(409, `A variable named ${name} already exists in this environment`);
      console.error('global-variables create failed', error.message);
      throw new AuthError(500, 'Could not create the variable');
    }
    await audit(tenantId, environment, user.userId, 'create', data.id as string, { name, kind });
    return { variable: { ...data, value: kind === 'plain' ? stored : '', has_value: true } };
  },

  async update(user, p) {
    const row = await loadOwned(user, p.id);
    const patch: Json = { updated_at: new Date().toISOString() };
    if (p.description !== undefined) patch.description = textOf(p.description, 500, 'description').trim() || null;
    if (p.scopes !== undefined) patch.scopes = scopesOf(p.scopes);
    if (p.value !== undefined && p.value !== '') {
      if (row.kind === 'encryption_key') throw new AuthError(400, 'Use rotate to replace an encryption key');
      const value = textOf(p.value, 4000, 'value');
      patch.value = row.kind === 'secret' ? await sealSecret(value) : value;
    }
    const { error } = await getServiceClient().from('global_variables').update(patch).eq('id', row.id);
    if (error) throw new AuthError(500, 'Could not update the variable');
    await audit(row.tenant_id, row.environment, user.userId, 'update', row.id, { name: row.name, value_changed: 'value' in patch });
    return { updated: true };
  },

  async rotate(user, p) {
    const row = await loadOwned(user, p.id);
    if (row.kind !== 'encryption_key') throw new AuthError(400, 'Only encryption keys can be rotated');
    const key = generateDataKey();
    const now = new Date().toISOString();
    const { error } = await getServiceClient().from('global_variables')
      .update({ value: await sealSecret(key), fingerprint: await dataKeyFingerprint(key), rotated_at: now, updated_at: now }).eq('id', row.id);
    if (error) throw new AuthError(500, 'Could not rotate the key');
    await audit(row.tenant_id, row.environment, user.userId, 'rotate', row.id, { name: row.name });
    return { rotated: true };
  },

  async reveal(user, p) {
    const row = await loadOwned(user, p.id);
    if (row.kind === 'encryption_key') throw new AuthError(403, 'Encryption keys are never revealed');
    if (row.value && !isSealed(String(row.value))) {
      throw new AuthError(409, 'This value was saved in the old format and can no longer be read — enter it again');
    }
    const found = await loadVariablePlaintext(getServiceClient(), row.tenant_id, row.environment, row.name, 'all');
    await audit(row.tenant_id, row.environment, user.userId, 'reveal', row.id, { name: row.name });
    return { value: found?.plaintext ?? '' };
  },

  async delete(user, p) {
    const row = await loadOwned(user, p.id);
    const { error } = await getServiceClient().from('global_variables').delete().eq('id', row.id);
    if (error) throw new AuthError(500, 'Could not delete the variable');
    await audit(row.tenant_id, row.environment, user.userId, 'delete', row.id, { name: row.name, kind: row.kind });
    return { deleted: true };
  },

  async encrypt_fields(user, p) {
    const tenantId = await resolveTenant(user, p.tenant_id);
    const environment = envOf(p);
    const { key, fields } = await fieldKey(tenantId, environment, p);
    const data = (p.data && typeof p.data === 'object' && !Array.isArray(p.data)) ? (p.data as Json) : null;
    if (!data) throw new AuthError(400, 'data must be an object');
    return { data: await encryptFieldsWithKey(data, fields, key) };
  },

  async decrypt_fields(user, p) {
    const tenantId = await resolveTenant(user, p.tenant_id);
    await requirePermission(user, tenantId, 'customers.read', 'View customer data');
    const environment = envOf(p);
    const { key, fields } = await fieldKey(tenantId, environment, p);
    const records = Array.isArray(p.records) ? (p.records as Json[]).slice(0, 500) : [];
    const out = [];
    for (const r of records) {
      const data = (r?.data && typeof r.data === 'object') ? (r.data as Json) : {};
      out.push({ id: r?.id ?? null, data: await decryptFieldsWithKey(data, fields.length ? fields : Object.keys(data), key) });
    }
    return { records: out };
  },
};

async function fieldKey(tenantId: string, environment: string, p: Json) {
  const name = textOf(p.key_variable, 64, 'key_variable');
  const found = await loadVariablePlaintext(getServiceClient(), tenantId, environment, name, 'forms');
  if (!found || found.kind !== 'encryption_key') throw new AuthError(404, `Encryption key ${name} could not be resolved`);
  const fields = Array.isArray(p.fields) ? (p.fields as unknown[]).filter((f): f is string => typeof f === 'string').slice(0, 500) : [];
  return { key: found.plaintext, fields };
}

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders() });
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);
  try {
    const user = await authenticateUser(req);
    const body = (await req.json().catch(() => null)) as Json | null;
    if (!body || typeof body !== 'object' || Array.isArray(body)) return errorResponse('JSON body required', 400);
    const op = typeof body.op === 'string' ? body.op : '';
    const handler = Object.prototype.hasOwnProperty.call(ops, op) ? ops[op] : undefined;
    if (!handler) return errorResponse('Unknown operation', 400);
    return jsonResponse({ data: await handler(user, body) });
  } catch (e) {
    if (e instanceof AuthError) return errorResponse(e.message, e.status);
    console.error('global-variables unhandled', e instanceof Error ? e.message : e);
    return errorResponse('Internal error', 500);
  }
});
